// The concession-v1 normalizer against what the REAL revision 3 SDK emits:
// whole client snapshots and error objects generated by
// test/fixtures/zkapi-v2-real-shapes/regenerate.mjs from the SDK's own
// modules (README.md there says what is hand-seeded and what is emitted).
//
// Everything is relative to the fixtures' frozen clock: tests inject
// `now = generatedAtMs + offset` and never read Date.now() against the
// committed instants.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import test from 'node:test';
import concessionV1 from '../../chat/zkapi/versioning/adapters/concessionV1.mjs';
import noteBoundV1, { emptyNormalizedSnapshot } from '../../chat/zkapi/versioning/adapters/noteBoundV1.mjs';
import { readWalletHoldings } from '../../chat/zkapi/versioning/walletHoldings.mjs';
import { createFakeEnvironment } from './_fakeIndexedDb.mjs';

const fixtureUrl = name => new URL(`../fixtures/zkapi-v2-real-shapes/${name}`, import.meta.url);
const FIXTURES = JSON.parse(fs.readFileSync(fixtureUrl('snapshots.json'), 'utf8'));
const { scenarios, errors, deployments } = FIXTURES;

const G = FIXTURES.generatedAtMs;     // epoch ms
const S = G / 1000;                   // epoch s
const DAY = 86_400;
const WINDOW = FIXTURES.settlementWindowSeconds;
const MARGIN = 43_200;                // must_initiate_by = expiry - 12 h
const SLOT_EXPIRY = S + 14 * DAY;
const DESTINATION = `0x${'34'.repeat(20)}`;

// The facade hands the adapter the client snapshot with its runtime slot
// merged in; both forms are exercised.
const facadeSnapshot = name => ({ ...scenarios[name].clientSnapshot, runtime: scenarios[name].runtime });
const clientSnapshot = name => scenarios[name].clientSnapshot;
const normalize = (name, { slot = true, now = G } = {}) => concessionV1.normalizeSnapshot(
    slot ? facadeSnapshot(name) : clientSnapshot(name), { nowMs: now });

const recordId = (deploymentId, vault, noteId) => `${deploymentId}:1:${vault.toLowerCase()}:${noteId}`;
const CURRENT_VAULT = `0x${'22'.repeat(20)}`;
const PREVIOUS_VAULT = '0x4386FDbdA35D995beB3BF8625118Ec5982ec81fe';
const RETIRED_VAULT = `0x${'66'.repeat(20)}`;
const ownRecord = noteId => recordId(deployments.current, CURRENT_VAULT, noteId);

// A healthy slot note, then what each scenario changes.
function slotExpectation(changes = {}) {
    const { exit = {}, ...rest } = changes;
    const expiryTs = rest.expiryTs ?? SLOT_EXPIRY;
    return {
        hasNote: true, expiryTs, deadlines: [{ source: 'slot', expiryTs }],
        hasPendingDeposit: false, hasUnsentPrepared: false, hasPreparedWithdrawal: false, hasOpenWithdrawal: false,
        sdkDepositsClosed: false,
        service: { available: true, code: null, message: null },
        otherDeploymentWithdrawals: [], otherDeploymentCredits: [],
        ownCredits: [], payoutAlerts: [], deviceNotNewestRecords: [], setAsideNear: [], unresolvedRequests: 0,
        ...rest,
        exit: {
            mustInitiateBy: (expiryTs - MARGIN) * 1000, nearExpiry: false, lockHeld: false, kitOutOfDate: true,
            rpcRecommended: false, boundAtState: '0', stateFresh: true, escapeAt: null, deviceNotNewest: false, lock: null,
            kit: { stateSeq: 2, exportedSeq: null, outOfDate: true },
            depositPathSaved: true, rpcWrongChain: false, costWarning: false,
            ...exit
        }
    };
}
const exitOnly = code => ({
    available: false, code, message: scenarios.service_missing.clientSnapshot.config.service.message
});

// ---------------------------------------------------------------------------
// The fixtures themselves
// ---------------------------------------------------------------------------

test('the fixture set is the documented one and carries the SDK units it documents', () => {
    assert.equal(G, Date.UTC(2026, 10, 15, 12));
    assert.deepEqual(Object.keys(scenarios), [
        'service_missing', 'service_changed', 'service_legacy', 'kit_never_exported', 'kit_out_of_date', 'near_expiry',
        'just_outside_near_expiry', 'unresolved_request_settlement_wait', 'mutual_lock_with_ownership_proof',
        'escape_lock_released_proof', 'device_not_newest_evidence', 'withdrawals_alert_credited_defeated',
        'other_deployments'
    ]);
    // Every file records the SDK bytes it came from, and is deterministic.
    for (const name of ['snapshots.json', 'oracle-vectors.json', 'wallet-db-v2.json']) {
        const file = JSON.parse(fs.readFileSync(fixtureUrl(name), 'utf8'));
        assert.equal(file.generatedAtMs, G, name);
        assert.match(file.source.files['services/browserWalletRuntime.js'], /^[0-9a-f]{64}$/, name);
    }
    // Milliseconds (the exit summary, the set-aside record fields, the withdraw
    // settlement refusal) versus seconds (lock and release refusals, notes).
    const ms = value => Number.isInteger(value) && value > 1e12 && Math.abs(value - G) < 120 * DAY * 1000;
    const seconds = value => Number.isInteger(value) && value > 1e9 && value < 1e11 && Math.abs(value - S) < 120 * DAY;
    for (const [name, { clientSnapshot: snapshot }] of Object.entries(scenarios)) {
        const exit = snapshot.config.exit;
        if (exit) {
            assert.ok(ms(exit.must_initiate_by), `${name}.must_initiate_by`);
            for (const value of [exit.escape_at, exit.lock?.since, exit.lock?.releasable_after]) {
                if (value != null) assert.ok(ms(value), `${name}: ${value}`);
            }
        }
        for (const record of snapshot.withdrawals) {
            for (const key of ['expiry', 'must_initiate_by']) {
                if (record[key] != null) assert.ok(ms(record[key]), `${name}.${record.recordId}.${key}`);
            }
        }
        if (snapshot.wallet.note) assert.ok(seconds(snapshot.wallet.note.expiry_ts), `${name} note expiry`);
    }
    assert.ok(ms(errors.request_settlement_pending_withdraw.data.escape_at));
    assert.ok(ms(errors.request_settlement_pending_withdraw.data.must_initiate_by));
    assert.ok(seconds(errors.exit_locked.data.releasable_after));
    assert.ok(seconds(errors.exit_release_pending.data.releasable_after));
    assert.ok(seconds(errors.exit_release_pending.data.must_initiate_by));
    assert.equal(errors.ownership_proof_wait.data.retry_after, 4, 'seconds from now, not an instant');
    // Service refusals carry status 503 and exits true; the legacy SDK's own
    // incompatible-circuit refusal is a plain Error with neither.
    for (const name of ['service_unavailable', 'service_mismatch', 'service_incompatible', 'native_vault_unverified']) {
        assert.equal(errors[name].status, 503, name);
        assert.deepEqual(errors[name].data, { exits: true }, name);
    }
    assert.equal(errors.legacy_incompatible_proof_circuit.code, 'incompatible_proof_circuit');
    assert.equal(errors.legacy_incompatible_proof_circuit.status, null);
    assert.equal(errors.legacy_incompatible_proof_circuit.data, null);
    // The chat and the withdraw shapes of request_settlement_pending differ.
    assert.deepEqual(errors.request_settlement_pending_chat.data, { nullifier_status: 'reserved' });
    assert.equal(errors.request_settlement_pending_withdraw.data.escape_at !== undefined, true);
    for (const error of Object.values(errors)) assert.equal(error.handSeeded, false);
});

// ---------------------------------------------------------------------------
// Exact normalized objects, one per scenario
// ---------------------------------------------------------------------------

test('service: each exit-only cause normalizes with its code, never with the operator detail', () => {
    const cases = [
        ['service_missing', 'deployment_manifest_unavailable'],
        ['service_changed', 'deployment_manifest_mismatch'],
        ['service_legacy', 'incompatible_proof_circuit']
    ];
    for (const [name, code] of cases) {
        assert.deepEqual(normalize(name), slotExpectation({ service: exitOnly(code) }), name);
        // The snapshot's `detail` embeds the operator's URL and pin names.
        assert.match(scenarios[name].clientSnapshot.config.service.detail, /\S/);
        assert.doesNotMatch(JSON.stringify(normalize(name)), /example\.test|state_signing_key|legacy proof circuit/);
    }
    // The same codes are what an attempt then throws.
    assert.equal(errors.service_unavailable.code, 'deployment_manifest_unavailable');
    assert.equal(errors.service_mismatch.code, 'deployment_manifest_mismatch');
    assert.equal(errors.service_incompatible.code, 'incompatible_proof_circuit');
    // Deposits stay "open" in the snapshot: the host derives closure itself.
    assert.equal(scenarios.service_missing.clientSnapshot.config.deposits, 'open');
    assert.equal(normalize('service_missing').sdkDepositsClosed, false);
});

test('exit kit: never exported and out of date read as such, with the sequences', () => {
    assert.deepEqual(normalize('kit_never_exported'), slotExpectation({
        exit: { kit: { stateSeq: 1, exportedSeq: null, outOfDate: true } }
    }));
    assert.deepEqual(normalize('kit_out_of_date'), slotExpectation({
        exit: { kit: { stateSeq: 3, exportedSeq: 1, outOfDate: true } }
    }));
});

test('near expiry: the SDK flag flips at must_initiate_by minus the window and the margin, not at 24 hours', () => {
    // The SDK pauses new chats once now + window + 75 minutes passes the
    // instant an exit must start (note expiry minus 12 hours).
    const threshold = expiryTs => (expiryTs - MARGIN) - (WINDOW + 4_500);
    const near = normalize('near_expiry');
    const outside = normalize('just_outside_near_expiry');
    // One minute inside, one hour outside the real threshold.
    assert.equal(near.exit.nearExpiry, true);
    assert.equal(outside.exit.nearExpiry, false);
    assert.equal(near.exit.mustInitiateBy, (near.expiryTs - MARGIN) * 1000);
    assert.equal(near.expiryTs, S + 43_200 + WINDOW + 4_500 - 60);
    assert.equal(outside.expiryTs, S + 43_200 + WINDOW + 4_500 + 3_600);
    // At the fixtures' clock the near note is 60 s past the pause instant and
    // the other is an hour before it.
    assert.equal(S - threshold(near.expiryTs), 60);
    assert.equal(S - threshold(outside.expiryTs), -3_600);
    // Both are far more than a day from their expiry, which is what a
    // fabricated 24-hour rule would have said.
    assert.ok(near.expiryTs - S > 19 * 3_600);
    assert.deepEqual(near, slotExpectation({ expiryTs: near.expiryTs, exit: { nearExpiry: true } }));
    assert.deepEqual(outside, slotExpectation({ expiryTs: outside.expiryTs }));
});

test('an unresolved request: freshness, the bound, the earliest escape time and the count', () => {
    const created = G - 600_000;
    assert.deepEqual(normalize('unresolved_request_settlement_wait'), slotExpectation({
        unresolvedRequests: 1,
        exit: {
            stateFresh: false, boundAtState: '1000000',
            // The request's creation plus the settlement window and 15 minutes.
            escapeAt: created + (WINDOW + 900) * 1000
        }
    }));
    // The withdraw refusal quotes the same numbers, as strings and ms.
    const refusal = errors.request_settlement_pending_withdraw.data;
    assert.equal(refusal.escape_at, normalize('unresolved_request_settlement_wait').exit.escapeAt);
    assert.equal(refusal.bound_at_state, normalize('unresolved_request_settlement_wait').exit.boundAtState);
});

test('exit locks: a mutual close holding an ownership proof, an escape holding an exit proof', () => {
    assert.deepEqual(normalize('mutual_lock_with_ownership_proof'), slotExpectation({
        exit: { lockHeld: true, lock: { mode: 'mutual', sinceMs: G - 30_000, released: 1, proofsReleased: 0,
            releasableAfterMs: null } }
    }));
    // An exit proof is dead 15 minutes after its valid_until.
    assert.deepEqual(normalize('escape_lock_released_proof'), slotExpectation({
        hasPreparedWithdrawal: true,
        exit: { lockHeld: true, lock: { mode: 'escape', sinceMs: G - 30_000, released: 1, proofsReleased: 1,
            releasableAfterMs: (S + 10_800 + 900) * 1000 } }
    }));
});

test('defeat evidence at the state reads as device not newest and counts as an unresolved record', () => {
    assert.deepEqual(normalize('device_not_newest_evidence'), slotExpectation({
        unresolvedRequests: 1, exit: { deviceNotNewest: true }
    }));
});

test('own records: alert, credits of both evidences, a claimed credit, a defeated restore and a near set-aside note', () => {
    const result = normalize('withdrawals_alert_credited_defeated');
    const nearExpiry = S + 3 * DAY + 43_200;
    const defeatedExpiry = S + 10 * DAY;
    assert.deepEqual(result, {
        hasNote: false, expiryTs: null,
        // Soonest first; only the concession family says which record and
        // whether this device may still exit it.
        deadlines: [
            { source: 'set-aside', expiryTs: nearExpiry, recordId: ownRecord(8), deviceFlagged: false },
            { source: 'set-aside', expiryTs: defeatedExpiry, recordId: ownRecord(6), deviceFlagged: true }
        ],
        hasPendingDeposit: false, hasUnsentPrepared: false, hasPreparedWithdrawal: false,
        // The credited close not yet final, the restored and the parked record.
        hasOpenWithdrawal: true,
        sdkDepositsClosed: false,
        service: { available: true, code: null, message: null },
        otherDeploymentWithdrawals: [], otherDeploymentCredits: [],
        exit: null,
        // Unclaimed credits only: the claimed one is gone. The vault_credit
        // evidence has no amount this browser could read.
        ownCredits: [
            { recordId: ownRecord(3), noteId: 3, creditedAmount: '800000', evidence: 'receipt' },
            { recordId: ownRecord(4), noteId: 4, creditedAmount: null, evidence: 'vault_credit' }
        ],
        payoutAlerts: [ownRecord(2)],
        deviceNotNewestRecords: [ownRecord(6)],
        // The defeated record is also near nothing: it expires in ten days.
        setAsideNear: [{ recordId: ownRecord(8), mustInitiateByMs: (nearExpiry - MARGIN) * 1000, expiryMs: nearExpiry * 1000 }],
        unresolvedRequests: 0
    });
    // The SDK's own record fields behind that, as numbers.
    const byNote = Object.fromEntries(scenarios.withdrawals_alert_credited_defeated.clientSnapshot.withdrawals
        .map(record => [record.noteId, record]));
    assert.equal(typeof byNote[3].creditedAmount, 'number');
    assert.equal(byNote[4].creditedAmount, null);
    assert.equal(byNote[2].payoutAlert, 'concession_exceeded_bound');
    assert.equal(byNote[6].challengeObserved, true);
    assert.equal(byNote[6].deviceNotNewest, true);
    assert.equal(byNote[8].exit_deadline_near, true);
    assert.equal(byNote[6].exit_deadline_near, false);
});

test('wiring:other-deployment-credits: real credited amounts are numbers and keep their value as strings', () => {
    const result = normalize('other_deployments');
    assert.deepEqual(result.otherDeploymentCredits, [
        {
            deploymentId: deployments.retired, recordId: recordId(deployments.retired, RETIRED_VAULT, 20), noteId: 20,
            chainId: 1, contractAddress: RETIRED_VAULT.toLowerCase(), destination: DESTINATION, creditedAmount: '1500000'
        },
        {
            deploymentId: deployments.retired, recordId: recordId(deployments.retired, RETIRED_VAULT, 21), noteId: 21,
            chainId: 1, contractAddress: RETIRED_VAULT.toLowerCase(), destination: DESTINATION, creditedAmount: '42'
        }
    ]);
    // What the SDK wrote is a JS number: an adapter that only accepted
    // strings would have reported null here.
    for (const credit of scenarios.other_deployments.clientSnapshot.config.other_deployment_credits) {
        assert.equal(typeof credit.credited_amount, 'number');
    }
    // A decimal string (older stores, host holdings) and a bigint are the same amount.
    const credit = amount => concessionV1.normalizeSnapshot({ config: { other_deployment_credits: [{
        deployment_id: deployments.retired, record_id: 'r', note_id: 1, credited_amount: amount }] } })
        .otherDeploymentCredits[0].creditedAmount;
    assert.equal(credit(1500000), '1500000');
    assert.equal(credit('1500000'), '1500000');
    assert.equal(credit(1500000n), '1500000');
    assert.equal(credit(0), '0');
    // Not an amount: unknown, never a guess.
    for (const bad of [null, undefined, -1, 1.5, 'abc', '1e3', '-5', '', NaN, Infinity, {}, [], true, 2 ** 53]) {
        assert.equal(credit(bad), null, String(bad));
    }
});

test('wiring:other-deployment-withdrawals: other deployments\' open records are listed, a settled credit is not', () => {
    const result = normalize('other_deployments');
    assert.deepEqual(result.otherDeploymentWithdrawals, [
        { deploymentId: deployments.previous, recordId: recordId(deployments.previous, PREVIOUS_VAULT, 11), noteId: 11,
            mode: 'escape', phase: 'pending' },
        { deploymentId: deployments.previous, recordId: recordId(deployments.previous, PREVIOUS_VAULT, 12), noteId: 12,
            mode: 'mutual', phase: 'parked' },
        // Credited but not yet final: the SDK lists it as open AND as a credit.
        { deploymentId: deployments.retired, recordId: recordId(deployments.retired, RETIRED_VAULT, 20), noteId: 20,
            mode: 'escape', phase: 'closed_unconfirmed' }
    ]);
    // None of them is this deployment's own record or deadline.
    assert.deepEqual(result, {
        ...emptyNormalizedSnapshot(),
        ownCredits: [], payoutAlerts: [], deviceNotNewestRecords: [], setAsideNear: [], unresolvedRequests: 0,
        service: { available: true, code: null, message: null },
        otherDeploymentWithdrawals: result.otherDeploymentWithdrawals,
        otherDeploymentCredits: result.otherDeploymentCredits
    });
});

