test('every scenario normalizes without a secret, a URL or a raw field, and the slot only ever tightens', () => {
    for (const name of Object.keys(scenarios)) {
        const raw = JSON.stringify(facadeSnapshot(name));
        // The input does carry secrets and an operator URL ...
        assert.match(raw, /SECRET-|zkapi-v2c-mainnet\.example\.test/);
        const before = raw;
        const withSlot = normalize(name);
        const withoutSlot = normalize(name, { slot: false });
        // ... the output never does.
        assert.doesNotMatch(JSON.stringify(withSlot), /SECRET|example\.test|exit_rpc_url|0x1234/);
        // The input is not modified, and the slot changes nothing here (no
        // pending deposit exists in these scenarios).
        assert.equal(JSON.stringify(facadeSnapshot(name)), before);
        assert.deepEqual(withSlot, withoutSlot, name);
        // Pure and repeatable at any injected clock.
        assert.deepEqual(normalize(name, { now: G + 5 * DAY * 1000 }), withSlot);
        // Every key of the revision 3 shape is present, none undefined.
        for (const key of ['ownCredits', 'payoutAlerts', 'deviceNotNewestRecords', 'setAsideNear', 'unresolvedRequests',
            'service', 'exit', 'otherDeploymentWithdrawals', 'otherDeploymentCredits']) {
            assert.notEqual(withSlot[key], undefined, `${name}.${key}`);
        }
        // Deadlines are seconds; exit instants are milliseconds.
        for (const deadline of withSlot.deadlines) assert.ok(deadline.expiryTs < 1e11, name);
        if (withSlot.exit?.mustInitiateBy != null) assert.ok(withSlot.exit.mustInitiateBy > 1e12, name);
    }
});

test('the legacy adapter reads the same snapshots without the revision 3 fields', () => {
    const baseKeys = Object.keys(emptyNormalizedSnapshot()).sort();
    for (const name of Object.keys(scenarios)) {
        const legacy = noteBoundV1.normalizeSnapshot(facadeSnapshot(name), { nowMs: G });
        assert.deepEqual(Object.keys(legacy).sort(), baseKeys, name);
        assert.equal(legacy.service, null);
        assert.equal(legacy.exit, null);
        assert.deepEqual(legacy.otherDeploymentCredits, []);
        for (const deadline of legacy.deadlines) assert.deepEqual(Object.keys(deadline).sort(), ['expiryTs', 'source']);
    }
});

test('a defeated record is never nudged toward a withdrawal, and is not the slot note\'s deadline', () => {
    const result = normalize('withdrawals_alert_credited_defeated');
    const flagged = result.deadlines.filter(deadline => deadline.deviceFlagged);
    assert.deepEqual(flagged.map(deadline => deadline.recordId), [ownRecord(6)]);
    assert.ok(!result.setAsideNear.some(entry => entry.recordId === ownRecord(6)));
    // Matched by record, never by expiry seconds: changing the flagged
    // record's expiry to the near one's does not move the flag.
    const snapshot = structuredClone(clientSnapshot('withdrawals_alert_credited_defeated'));
    for (const record of snapshot.withdrawals) {
        if (record.noteId === 6) {
            record.expiry = snapshot.withdrawals.find(entry => entry.noteId === 8).expiry;
            record.exit_deadline_near = true;
        }
    }
    const moved = concessionV1.normalizeSnapshot(snapshot, { nowMs: G });
    assert.deepEqual(moved.deviceNotNewestRecords, [ownRecord(6)]);
    assert.deepEqual(moved.setAsideNear.map(entry => entry.recordId), [ownRecord(8)]);
    assert.equal(moved.deadlines.filter(deadline => deadline.deviceFlagged).length, 1);
});

// ---------------------------------------------------------------------------
// What the holdings watcher fingerprints
//
// The facade wakes the watcher (a read of the shared wallet database) when the
// adapter's reading changes. The SDK moves several facts of a revision 3
// reading on every settled chat or while one is in flight; those must not wake
// it, and everything a fresh load or a notice depends on must still do so.
// ---------------------------------------------------------------------------

const normalizedOf = snapshot => concessionV1.normalizeSnapshot(snapshot, { nowMs: G });
const factsOf = snapshot => concessionV1.watchFacts(normalizedOf(snapshot));
const json = value => JSON.stringify(value);
const changed = (name, change) => {
    const snapshot = structuredClone(facadeSnapshot(name));
    change(snapshot);
    return snapshot;
};

// Every leaf path of a reading; arrays are leaves (the projection never looks
// inside one).
function leafPaths(value, prefix = '') {
    if (value === null || typeof value !== 'object' || Array.isArray(value)) return [prefix];
    return Object.entries(value).flatMap(([key, child]) => leafPaths(child, prefix ? `${prefix}.${key}` : key));
}

// The facts the SDK moves per chat, named by the projection and nothing else.
const PER_CHAT_PATHS = [
    'unresolvedRequests', 'exit.boundAtState', 'exit.stateFresh', 'exit.escapeAt', 'exit.costWarning',
    'exit.lock.sinceMs', 'exit.kit.stateSeq', 'exit.kit.exportedSeq'
];

test('watch facts: a settled chat, a request in flight and a re-based lock move the reading but not the facts', () => {
    // Five settled chats: the SDK bumps the state sequence and nothing else.
    const idle = facadeSnapshot('kit_out_of_date');
    for (let chats = 1; chats <= 5; chats += 1) {
        const later = changed('kit_out_of_date', snapshot => {
            snapshot.config.exit.exit_kit.state_seq += chats;
            snapshot.runtime.stateSeq += chats;
        });
        assert.notEqual(json(normalizedOf(later)), json(normalizedOf(idle)), 'the reading itself does move');
        assert.equal(json(factsOf(later)), json(factsOf(idle)), `${chats} chats`);
    }

    // A request in flight: unresolved, not fresh, a bound and the earliest
    // escape time; the same note idle has none of them.
    const inFlight = facadeSnapshot('unresolved_request_settlement_wait');
    const settled = changed('unresolved_request_settlement_wait', snapshot => {
        snapshot.config.unresolved_requests = [];
        snapshot.config.exit.state_fresh = true;
        snapshot.config.exit.bound_at_state = '0';
        snapshot.config.exit.escape_at = null;
    });
    assert.equal(normalizedOf(inFlight).unresolvedRequests, 1);
    assert.equal(normalizedOf(settled).unresolvedRequests, 0);
    assert.notEqual(json(normalizedOf(inFlight)), json(normalizedOf(settled)));
    assert.equal(json(factsOf(inFlight)), json(factsOf(settled)));

    // A lock re-based onto the next state: the same lock, a later `since`.
    const locked = facadeSnapshot('mutual_lock_with_ownership_proof');
    const rebased = changed('mutual_lock_with_ownership_proof', snapshot => {
        snapshot.config.exit.lock.since += 60_000;
        snapshot.runtime.exitLock.since += 60;
    });
    assert.notEqual(json(normalizedOf(locked)), json(normalizedOf(rebased)));
    assert.equal(json(factsOf(locked)), json(factsOf(rebased)));

    // The cost warning follows the balance and the gas price.
    const warned = changed('kit_out_of_date', snapshot => {
        snapshot.config.exit.exit_cost_warning = { floor: '1000', cost: '400000', gas_price_wei: '40000000000' };
    });
    assert.equal(normalizedOf(warned).exit.costWarning, true);
    assert.equal(json(factsOf(warned)), json(factsOf(idle)));
});

test('watch facts: every fact a fresh load or a notice depends on still moves them', () => {
    const exit = change => snapshot => change(snapshot.config.exit, snapshot);
    const moves = [
        ['the slot note is gone', 'kit_out_of_date', snapshot => {
            snapshot.wallet = { has_note: false, pending_request: false, note: null };
            snapshot.runtime = { ...snapshot.runtime, state: null };
        }],
        ['the slot note\'s expiry', 'kit_out_of_date', snapshot => { snapshot.wallet.note.expiry_ts += 3_600; }],
        ['the SDK closes deposits', 'kit_out_of_date', snapshot => { snapshot.config.deposits = 'closed'; }],
        ['the service becomes unavailable', 'kit_out_of_date', snapshot => {
            snapshot.config.service = { available: false, exits: true, code: 'deployment_manifest_unavailable', message: 'Paused.' };
        }],
        ['the service code changes', 'service_missing', snapshot => { snapshot.config.service.code = 'deployment_manifest_mismatch'; }],
        ['another deployment has an unfinished withdrawal', 'kit_out_of_date', snapshot => {
            snapshot.config.other_deployment_withdrawals = [
                { deployment_id: deployments.previous, record_id: 'r-1', note_id: 1, mode: 'mutual', phase: 'parked' }
            ];
        }],
        ['another deployment credits a payout', 'kit_out_of_date', snapshot => {
            snapshot.config.other_deployment_credits = [{
                deployment_id: deployments.previous, record_id: 'r-2', note_id: 2, chain_id: 1,
                contract_address: PREVIOUS_VAULT, destination: DESTINATION, credited_amount: 5_000
            }];
        }],
        ['a deposit is pending', 'kit_out_of_date', snapshot => {
            snapshot.config.late_deposit_attempts = [{ recordId: 'late-1', phase: 'unknown' }];
        }],
        ['a withdrawal is prepared', 'kit_out_of_date', snapshot => { snapshot.config.prepared_withdrawal = { operationId: 'op-1' }; }],
        ['an own credit is claimed', 'withdrawals_alert_credited_defeated', snapshot => {
            snapshot.withdrawals.find(record => record.noteId === 3).payoutClaimed = true;
        }],
        ['a payout alert is cleared', 'withdrawals_alert_credited_defeated', snapshot => {
            delete snapshot.withdrawals.find(record => record.noteId === 2).payoutAlert;
        }],
        ['a record stops being device flagged', 'withdrawals_alert_credited_defeated', snapshot => {
            const record = snapshot.withdrawals.find(entry => entry.noteId === 6);
            record.challengeObserved = false;
            record.deviceNotNewest = false;
        }],
        ['a set-aside note leaves its warning window', 'withdrawals_alert_credited_defeated', snapshot => {
            snapshot.withdrawals.find(record => record.noteId === 8).exit_deadline_near = false;
        }],
        ['the SDK flags near expiry', 'kit_out_of_date', exit(config => { config.near_expiry = true; })],
        ['a lock is taken', 'kit_out_of_date', exit(config => {
            config.lock = { mode: 'mutual', since: G, released: 0, exit_proofs_released: 0, releasable_after: null };
        })],
        ['a proof is released', 'mutual_lock_with_ownership_proof', exit(config => {
            config.lock.released += 1;
            config.lock.exit_proofs_released = 1;
            config.lock.releasable_after = G + 11_700_000;
        })],
        ['the lock changes mode', 'mutual_lock_with_ownership_proof', exit(config => { config.lock.mode = 'escape'; })],
        ['the exit kit is exported', 'kit_out_of_date', exit(config => {
            config.exit_kit.exported_seq = config.exit_kit.state_seq;
            config.exit_kit.out_of_date = false;
        })],
        ['the deposit path is lost', 'kit_out_of_date', exit(config => { config.deposit_path_saved = false; })],
        ['an exit RPC is recommended', 'kit_out_of_date', exit(config => { config.exit_rpc_recommended = true; })],
        ['the exit RPC is on another chain', 'kit_out_of_date', exit(config => { config.exit_rpc_wrong_chain = true; })],
        ['the device is no longer the newest', 'kit_out_of_date', exit(config => { config.device_not_newest = true; })]
    ];
    for (const [label, name, change] of moves) {
        const before = factsOf(facadeSnapshot(name));
        const after = factsOf(changed(name, change));
        assert.notEqual(json(after), json(before), label);
    }
});

test('watch facts: only the named per-chat facts are left out, and a new field stays in', () => {
    // Over every scenario, the leaves dropped are exactly the named ones, and
    // together they cover all of them (so a misspelled name cannot pass).
    const dropped = new Set();
    for (const name of Object.keys(scenarios)) {
        const reading = normalizedOf(facadeSnapshot(name));
        const facts = concessionV1.watchFacts(reading);
        const kept = new Set(leafPaths(facts));
        for (const path of leafPaths(reading)) {
            if (kept.has(path)) continue;
            dropped.add(path);
            assert.ok(PER_CHAT_PATHS.includes(path), `${name}: ${path} is not a named per-chat fact`);
        }
        assert.doesNotMatch(json(facts), /SECRET|example\.test|exit_rpc_url/, name);
    }
    assert.deepEqual([...dropped].sort(), [...PER_CHAT_PATHS].sort());

    // A key the projection does not name is part of the facts at every level.
    const reading = normalizedOf(facadeSnapshot('mutual_lock_with_ownership_proof'));
    const extended = {
        ...reading, brandNew: 1,
        exit: { ...reading.exit, brandNewExit: 2,
            lock: { ...reading.exit.lock, brandNewLock: 3 },
            kit: { ...reading.exit.kit, brandNewKit: 4 } }
    };
    const facts = concessionV1.watchFacts(extended);
    assert.equal(facts.brandNew, 1);
    assert.equal(facts.exit.brandNewExit, 2);
    assert.equal(facts.exit.lock.brandNewLock, 3);
    assert.equal(facts.exit.kit.brandNewKit, 4);
});

test('watch facts: pure, never throws, and a reading without exit rules is passed through whole', () => {
    const reading = normalizedOf(facadeSnapshot('mutual_lock_with_ownership_proof'));
    const before = json(reading);
    const facts = concessionV1.watchFacts(reading);
    // The reading is untouched and the facts are a new object at every level
    // that was narrowed.
    assert.equal(json(reading), before);
    assert.notEqual(facts, reading);
    assert.notEqual(facts.exit, reading.exit);
    assert.notEqual(facts.exit.lock, reading.exit.lock);
    assert.notEqual(facts.exit.kit, reading.exit.kit);
    assert.equal(reading.exit.lock.sinceMs, G - 30_000);
    assert.equal(json(concessionV1.watchFacts(reading)), json(facts));

    // No exit block (no slot note), a missing lock and anything that is not a
    // reading.
    const noExit = normalizedOf(facadeSnapshot('withdrawals_alert_credited_defeated'));
    assert.equal(noExit.exit, null);
    assert.deepEqual(concessionV1.watchFacts(noExit), (({ unresolvedRequests, ...rest }) => rest)(noExit));
    const unlocked = concessionV1.watchFacts(normalizedOf(facadeSnapshot('kit_out_of_date')));
    assert.equal(unlocked.exit.lock, null);
    for (const input of [null, undefined, 7, 'x', [], true]) assert.equal(concessionV1.watchFacts(input), input);
    assert.deepEqual(concessionV1.watchFacts({ exit: 5, unresolvedRequests: 2 }), { exit: 5 });
    assert.deepEqual(concessionV1.watchFacts({ exit: { lock: 'x', kit: [1] } }), { exit: { lock: 'x', kit: [1] } });
});

// ---------------------------------------------------------------------------
// The oracle vectors are data the host's ports are replayed against; they are
// checked here once for being well formed and for meaning what they claim.
// ---------------------------------------------------------------------------

const VECTORS = JSON.parse(fs.readFileSync(fixtureUrl('oracle-vectors.json'), 'utf8'));

test('oracle vectors: expiry derivations are the SDK\'s, and the generations differ only on credited payouts', async () => {
    const { deriveExpiryRecords } = await import('@openanonymity/zkapi-browser-sdk/expiry-history');
    assert.ok(VECTORS.deriveExpiryRecords.length >= 100);
    let escapeClause = 0;
    let credited = 0;
    let claimed = 0;
    let differs = 0;
    for (const vector of VECTORS.deriveExpiryRecords) {
        assert.ok(Number.isInteger(vector.nowMs) && vector.nowMs >= G - DAY * 1000);
        const mentionsCredit = vector.withdrawals.some(record => record.payoutCredited === true);
        if (mentionsCredit) credited += 1;
        if (vector.output.some(record => record.status === 'claimed')) claimed += 1;
        if (vector.withdrawals.some(record => record.mode === 'escape' && record.chainStatus === 'pending_withdrawal'
            && record.startBlockNumber > 0 && record.finalizedBlockNumber >= record.startBlockNumber)) escapeClause += 1;
        // The installed legacy SDK's function on the same input. Without a
        // credited payout in play the two generations are the same function.
        const legacy = deriveExpiryRecords(structuredClone(vector.deposits), structuredClone(vector.withdrawals), vector.nowMs);
        if (JSON.stringify(legacy) !== JSON.stringify(vector.output)) {
            differs += 1;
            assert.ok(mentionsCredit, `a vector without a credited payout differs: ${JSON.stringify(vector)}`);
        }
    }
    // The set exercises each branch the host's port must reproduce.
    assert.ok(escapeClause > 3 && credited > 20 && claimed > 5, JSON.stringify({ escapeClause, credited, claimed }));
    assert.ok(differs > 0, 'the credited-payout clause is the one that distinguishes the generations');
});

test('oracle vectors: price conversions follow the documented integer formulas', () => {
    const MAX_SAFE = BigInt(Number.MAX_SAFE_INTEGER);
    assert.deepEqual(VECTORS.chatSpendingTierUsd, [1, 2, 3, 4.5, 6]);
    assert.ok(VECTORS.nativeUnitsForUsd.length >= 90 && VECTORS.nativeUsdMicros.length >= 70);
    const micros = text => {
        const [whole, fraction = ''] = text.split('.');
        return BigInt(whole) * 1_000_000n + BigInt(fraction.padEnd(6, '0'));
    };
    for (const vector of VECTORS.nativeUnitsForUsd) {
        const { answer, decimals } = vector.quote;
        const numerator = micros(vector.usd) * 1_000_000_000n * 10n ** BigInt(decimals);
        const denominator = BigInt(answer) * 1_000_000n;
        const units = (numerator + denominator - 1n) / denominator;
        if (units <= 0n || units > MAX_SAFE) {
            assert.equal(vector.output, null, JSON.stringify(vector));
            assert.ok(vector.error, JSON.stringify(vector));
        } else {
            assert.equal(vector.output, String(units), JSON.stringify(vector));
            assert.equal(vector.error, null);
        }
    }
    for (const vector of VECTORS.nativeUsdMicros) {
        const { answer, decimals } = vector.quote;
        const usd = BigInt(vector.units) * BigInt(answer) * 1_000_000n / (1_000_000_000n * 10n ** BigInt(decimals));
        assert.equal(vector.output, String(usd), JSON.stringify(vector));
    }
    // Prices reach both extremes the SDK accepts, and the extremes matter:
    // at answer 1 a dollar is more than the safe range of units.
    const labels = new Set(VECTORS.nativeUnitsForUsd.map(vector => vector.label));
    for (const label of ['$3,000 ETH', '$200,000 ETH', 'answer 1', 'answer 1e18']) assert.ok(labels.has(label), label);
    const extreme = VECTORS.nativeUnitsForUsd.find(vector => vector.label === 'answer 1' && vector.usd === '1');
    assert.equal(extreme.output, null);
    // At $3,000 a dollar is 333,333.33 gwei: rounded up, never down.
    const dollar = VECTORS.nativeUnitsForUsd.find(vector => vector.label === '$3,000 ETH' && vector.usd === '1');
    assert.equal(dollar.output, '333334');
});

