// The wallet database dump
// ---------------------------------------------------------------------------

test('the wallet database dump loads into the fake IndexedDB and the host\'s own probe reads it without writing', async () => {
    const wallet = JSON.parse(fs.readFileSync(fixtureUrl('wallet-db-v2.json'), 'utf8'));
    assert.equal(wallet.databaseName, 'zkapi-browser-wallet-v1');
    assert.deepEqual(Object.keys(wallet.dump.stores).sort(), ['archives', 'deposits', 'runtime', 'withdrawals']);
    const env = createFakeEnvironment();
    const restore = env.install();
    try {
        env.idb.seed('zkapi-browser-wallet-fixture-v1', wallet.dump);
        const before = JSON.stringify(env.idb.dump());
        const { holdings, slot } = await readWalletHoldings({ database: 'zkapi-browser-wallet-fixture-v1' });
        assert.equal(JSON.stringify(env.idb.dump()), before, 'reading wrote nothing');
        // The slot holds the current deployment's note.
        assert.deepEqual(slot, { deploymentId: wallet.deployments.current, kind: 'note' });
        const byDeployment = Object.fromEntries(holdings.map(holding => [holding.deploymentId, holding]));
        assert.deepEqual(Object.keys(byDeployment).sort(), [wallet.deployments.current, wallet.deployments.previous].sort());
        // Open records of the current deployment: the credited close awaiting
        // finality and the defeated restore. Its unclaimed credit is the one
        // not claimed; the alerted close and the retired deployment's
        // returned note hold nothing.
        const current = byDeployment[wallet.deployments.current];
        assert.equal(current.runtime, true);
        assert.deepEqual(current.withdrawals.map(record => [record.noteId, record.phase]).sort(), [[3, 'closed_unconfirmed'], [6, 'restored']]);
        assert.deepEqual(current.credits.map(credit => [credit.noteId, credit.creditedAmount]), [[3, '800000']]);
        const previous = byDeployment[wallet.deployments.previous];
        assert.equal(previous.runtime, false);
        assert.deepEqual(previous.withdrawals.map(record => [record.noteId, record.phase]), [[6, 'parked']]);
        assert.deepEqual(previous.credits, []);
    } finally {
        restore();
    }
    // Private fields are in the dump on purpose: the history view must project.
    const text = JSON.stringify(wallet.dump);
    for (const marker of ['SECRET-secret_s', 'SECRET-proof', 'SECRET-request-proof', 'SECRET-clearance-signature']) {
        assert.ok(text.includes(marker), marker);
    }
    // The two archive prefixes the history reader must never fetch are there.
    const archiveIds = Object.keys(wallet.dump.stores.archives.records);
    assert.ok(archiveIds.some(id => id.startsWith('request-journal:')));
    assert.ok(archiveIds.some(id => id.startsWith('request-evidence:')));
    assert.ok(archiveIds.some(id => !id.startsWith('request-')));
});
